/**
 * Integration Test Suite - Exports
 *
 * Centralized exports for all integration test utilities
 */

// Re-export setup utilities
export {
  TestUtils,
  MockData,
  PerfUtils,
  IntegrationMatchers,
  TEST_DB_DIR
} from './setup';

// Re-export fixtures
export {
  AgentFixtures,
  TaskFixtures,
  MemoryFixtures,
  WorkflowFixtures,
  PluginFixtures,
  ConfigFixtures,
  EventFixtures,
  ErrorFixtures,
  MockImplementations,
  Generators
} from './fixtures';

// Export commonly used types
export type IntegrationTestContext = {
  testDbPath: string;
  testDir: string;
  cleanup: () => Promise<void>;
};

// Export test helper functions
export const createTestContext = async (prefix: string): Promise<IntegrationTestContext> => {
  const { TestUtils } = await import('./setup');

  const testDbPath = TestUtils.createTestDbPath(prefix);
  const testDir = await TestUtils.createTestDir(prefix);

  return {
    testDbPath,
    testDir,
    cleanup: async () => {
      await TestUtils.cleanupTestFiles(prefix);
    }
  };
};

/**
 * Quick test setup for common scenarios
 */
export const quickSetup = {
  /**
   * Setup for memory tests
   */
  async memory() {
    const { TestUtils } = await import('./setup');
    const { MockImplementations } = await import('./fixtures');

    const dbPath = TestUtils.createTestDbPath('memory');
    const backend = MockImplementations.createMockMemoryBackend();

    return {
      dbPath,
      backend,
      cleanup: async () => {
        await backend.close();
        await TestUtils.cleanupTestFiles('memory');
      }
    };
  },

  /**
   * Setup for swarm tests
   */
  async swarm() {
    const { MockImplementations } = await import('./fixtures');

    const coordinator = MockImplementations.createMockCoordinator();

    return {
      coordinator,
      cleanup: async () => {
        await coordinator.shutdown();
      }
    };
  },

  /**
   * Setup for plugin tests
   */
  async plugin() {
    const { MockImplementations } = await import('./fixtures');

    const pluginManager = MockImplementations.createMockPluginManager();

    return {
      pluginManager,
      cleanup: async () => {
        await pluginManager.shutdown();
      }
    };
  },

  /**
   * Setup for full integration tests
   */
  async full() {
    const { TestUtils } = await import('./setup');
    const { MockImplementations } = await import('./fixtures');

    const dbPath = TestUtils.createTestDbPath('full');
    const backend = MockImplementations.createMockMemoryBackend();
    const coordinator = MockImplementations.createMockCoordinator();
    const pluginManager = MockImplementations.createMockPluginManager();

    return {
      dbPath,
      backend,
      coordinator,
      pluginManager,
      cleanup: async () => {
        await pluginManager.shutdown();
        await coordinator.shutdown();
        await backend.close();
        await TestUtils.cleanupTestFiles('full');
      }
    };
  }
};

/**
 * Common assertion helpers
 */
export const assert = {
  /**
   * Assert operation completed within time limit
   */
  async withinTime<T>(
    operation: () => Promise<T>,
    maxMs: number,
    message?: string
  ): Promise<T> {
    const start = Date.now();
    const result = await operation();
    const duration = Date.now() - start;

    if (duration > maxMs) {
      throw new Error(
        message || `Operation took ${duration}ms, expected <${maxMs}ms`
      );
    }

    return result;
  },

  /**
   * Assert operation succeeds after retries
   */
  async eventuallySucceeds<T>(
    operation: () => Promise<T>,
    maxAttempts: number = 3,
    delayMs: number = 100
  ): Promise<T> {
    const { TestUtils } = await import('./setup');
    return TestUtils.retry(operation, maxAttempts, delayMs);
  },

  /**
   * Assert condition becomes true
   */
  async eventuallyTrue(
    condition: () => boolean | Promise<boolean>,
    timeoutMs: number = 5000,
    intervalMs: number = 100
  ): Promise<void> {
    const { TestUtils } = await import('./setup');
    return TestUtils.waitFor(condition, timeoutMs, intervalMs);
  }
};

/**
 * Performance testing helpers
 */
export const perf = {
  /**
   * Measure execution time
   */
  async measure<T>(fn: () => Promise<T>): Promise<{ result: T; duration: number }> {
    const { TestUtils } = await import('./setup');
    return TestUtils.measureTime(fn);
  },

  /**
   * Benchmark function
   */
  async benchmark(
    name: string,
    fn: () => Promise<void>,
    iterations: number = 10
  ) {
    const { PerfUtils } = await import('./setup');
    return PerfUtils.benchmark(name, fn, iterations);
  },

  /**
   * Assert performance target
   */
  assertTarget(duration: number, targetMs: number, operation: string): void {
    const { PerfUtils } = await import('./setup');
    PerfUtils.assertPerformance(duration, targetMs, operation);
  }
};

/**
 * Data generation helpers
 */
export const generate = {
  /**
   * Generate test agents
   */
  agents(count: number) {
    return import('./fixtures').then(({ MockData }) => MockData.generateAgents(count));
  },

  /**
   * Generate test tasks
   */
  tasks(count: number) {
    return import('./fixtures').then(({ MockData }) => MockData.generateTasks(count));
  },

  /**
   * Generate test memories
   */
  memories(count: number, agentId?: string) {
    return import('./fixtures').then(({ MockData }) =>
      MockData.generateMemories(count, agentId)
    );
  },

  /**
   * Generate embedding vector
   */
  embedding(dimension: number = 384) {
    return import('./setup').then(({ TestUtils }) =>
      TestUtils.generateEmbedding(dimension)
    );
  }
};

// Default export with all utilities
export default {
  quickSetup,
  assert,
  perf,
  generate,
  createTestContext
};

import { describe, it, expect, beforeEach, afterEach, vi } from 'vitest';
import { MCPServer } from '../../src/infrastructure/mcp/MCPServer';
import { AgentTools } from '../../src/infrastructure/mcp/tools/AgentTools';
import { MemoryTools } from '../../src/infrastructure/mcp/tools/MemoryTools';
import { ConfigTools } from '../../src/infrastructure/mcp/tools/ConfigTools';
import { SwarmCoordinator } from '../../src/coordination/application/SwarmCoordinator';
import { HybridBackend } from '../../src/memory/infrastructure/HybridBackend';

describe('MCP Tools Integration Tests', () => {
  let mcpServer: MCPServer;
  let agentTools: AgentTools;
  let memoryTools: MemoryTools;
  let configTools: ConfigTools;
  let coordinator: SwarmCoordinator;
  let memoryBackend: HybridBackend;

  beforeEach(async () => {
    memoryBackend = {
      store: vi.fn(),
      retrieve: vi.fn(),
      query: vi.fn().mockResolvedValue([]),
      vectorSearch: vi.fn().mockResolvedValue([]),
      initialize: vi.fn(),
      close: vi.fn()
    } as any;

    coordinator = {
      spawnAgent: vi.fn(),
      listAgents: vi.fn().mockResolvedValue([]),
      terminateAgent: vi.fn(),
      getAgentMetrics: vi.fn(),
      initialize: vi.fn(),
      shutdown: vi.fn()
    } as any;

    agentTools = new AgentTools(coordinator);
    memoryTools = new MemoryTools(memoryBackend);
    configTools = new ConfigTools();

    mcpServer = new MCPServer({
      tools: [agentTools, memoryTools, configTools]
    });

    await mcpServer.start();
  });

  afterEach(async () => {
    await mcpServer.stop();
  });

  it('should spawn agent via MCP agent tools', async () => {
    const mockAgent = {
      id: 'mcp-agent-1',
      type: 'coder',
      status: 'active',
      capabilities: ['code', 'refactor']
    };

    (coordinator.spawnAgent as any).mockResolvedValue(mockAgent);

    const result = await agentTools.execute('agent_spawn', {
      id: 'mcp-agent-1',
      type: 'coder',
      capabilities: ['code', 'refactor']
    });

    expect(result.success).toBe(true);
    expect(result.agent.id).toBe('mcp-agent-1');
    expect(coordinator.spawnAgent).toHaveBeenCalledWith({
      id: 'mcp-agent-1',
      type: 'coder',
      capabilities: ['code', 'refactor']
    });
  });

  it('should list agents via MCP agent tools', async () => {
    const mockAgents = [
      { id: 'agent-1', type: 'coder', status: 'active' },
      { id: 'agent-2', type: 'tester', status: 'active' },
      { id: 'agent-3', type: 'reviewer', status: 'idle' }
    ];

    (coordinator.listAgents as any).mockResolvedValue(mockAgents);

    const result = await agentTools.execute('agent_list', {});

    expect(result.success).toBe(true);
    expect(result.agents).toHaveLength(3);
    expect(result.agents[0].id).toBe('agent-1');
  });

  it('should terminate agent via MCP agent tools', async () => {
    (coordinator.terminateAgent as any).mockResolvedValue({ success: true });

    const result = await agentTools.execute('agent_terminate', {
      agentId: 'agent-to-kill'
    });

    expect(result.success).toBe(true);
    expect(coordinator.terminateAgent).toHaveBeenCalledWith('agent-to-kill');
  });

  it('should get agent metrics via MCP agent tools', async () => {
    const mockMetrics = {
      agentId: 'metrics-agent',
      tasksCompleted: 10,
      averageExecutionTime: 250,
      successRate: 0.95,
      health: 'healthy'
    };

    (coordinator.getAgentMetrics as any).mockResolvedValue(mockMetrics);

    const result = await agentTools.execute('agent_metrics', {
      agentId: 'metrics-agent'
    });

    expect(result.success).toBe(true);
    expect(result.metrics.tasksCompleted).toBe(10);
    expect(result.metrics.successRate).toBe(0.95);
  });

  it('should store memory via MCP memory tools', async () => {
    const memory = {
      id: 'mcp-mem-1',
      agentId: 'agent-1',
      content: 'Test memory from MCP',
      type: 'task',
      timestamp: Date.now()
    };

    (memoryBackend.store as any).mockResolvedValue(memory);

    const result = await memoryTools.execute('memory_store', memory);

    expect(result.success).toBe(true);
    expect(memoryBackend.store).toHaveBeenCalledWith(memory);
  });

  it('should search memory via MCP memory tools', async () => {
    const mockMemories = [
