  it('should support hybrid search combining SQL and vector search', async () => {
    const memories: Memory[] = [
      {
        id: 'hybrid-1',
        agentId: 'agent-1',
        content: 'Machine learning optimization',
        type: 'task',
        timestamp: Date.now(),
